import http from 'k6/http';
import { check, fail } from 'k6';

export const options = {
  scenarios: {
    default: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 1,
    },
  },
};

const BASE_URL = (__ENV.BASE_URL || '').replace(/\/+$/, '');

export default function () {
  const loginRes = http.post(
    `${BASE_URL}/login`,
    JSON.stringify({ username: 'bench', password: 'bench' }),
    {
      headers: {
        'Content-Type': 'application/json',
      },
    }
  );

  check(loginRes, {
    'login succeeded': (r) => r.status >= 200 && r.status < 300,
  });

  let csrf = null;
  try {
    csrf = loginRes.json('csrf');
  } catch (e) {
    csrf = null;
  }

  if (!csrf) {
    fail('Failed to extract csrf token from login response');
  }

  const authHeaders = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
  };

  const productsRes = http.get(`${BASE_URL}/products`);
  check(productsRes, {
    'products succeeded': (r) => r.status >= 200 && r.status < 300,
  });

  const cartRes = http.post(
    `${BASE_URL}/cart`,
    JSON.stringify({ product_id: 'sku-1' }),
    { headers: authHeaders }
  );
  check(cartRes, {
    'cart succeeded': (r) => r.status >= 200 && r.status < 300,
  });

  const checkoutRes = http.post(
    `${BASE_URL}/checkout`,
    JSON.stringify({}),
    { headers: authHeaders }
  );
  check(checkoutRes, {
    'checkout succeeded': (r) => r.status >= 200 && r.status < 300,
  });
}
